/// <summary>
/// PaffH 15.11.21
/// see: http://kashperuk.blogspot.com/2017/03/development-tutorial-sysextension.html
/// </summary>
class NDXInstantiationStrategyForClassWithArg extends SysExtAppClassDefaultInstantiation
{
    str arg;
}

Method.Source:
public anytype instantiate(SysExtModelElement _element)
{
    SysExtModelElementApp appElement = _element as SysExtModelElementApp;
    Object instance;

    if (appElement)
    {
        SysDictClass dictClass = SysDictClass::newName(appElement.parmAppName());
        if (dictClass)
        {
            instance = dictClass.makeObject(arg);
        }
    }
    return instance;
}

public static NDXInstantiationStrategyForClassWithArg construct(str _arg)
{
    return new NDXInstantiationStrategyForClassWithArg(_arg);
}
